        fetch('/api/desa/pesisir/content').then(response=>response.ok?response.json():Promise.reject()).then(data=>{psProjects=Array.isArray(data.projects)?data.projects:[];if(!psProjects.length){psRenderProjects();return}[['year',psFilterYear],['status',psFilterStatus],['location',psFilterLocation]].forEach(([key,select])=>{[...new Set(psProjects.map(project=>String(project[key]||'')).filter(Boolean))].sort().forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)})});psFilters.hidden=false;psFilters.addEventListener('change',psRenderProjects);psFilters.addEventListener('reset',event=>{event.preventDefault();[psFilterYear,psFilterStatus,psFilterLocation].forEach(select=>select.value='');psRenderProjects()});psRenderProjects()}).catch(()=>{});
        const psQuestions=[{key:'title',prompt:'Apa usulan yang ingin disampaikan?',required:true,type:'text'},{key:'location',prompt:'Di mana usulan ini diperlukan?',required:true,type:'text'},{key:'category',prompt:'Pilih bidang usulan.',required:false,type:'choice',options:['Infrastruktur','Lingkungan','Sosial','Ekonomi','Lainnya']},{key:'description',prompt:'Jelaskan usulan secara singkat.',required:true,type:'textarea'},{key:'name',prompt:'Nama (opsional).',required:false,type:'text'},{key:'contact',prompt:'Kontak yang bisa dihubungi (opsional).',required:false,type:'text'}];let psAnswers={},psStep=0;const psChat=document.querySelector('#ps-chat'),psMessages=document.querySelector('#ps-chat-messages'),psControls=document.querySelector('#ps-chat-controls'),psActions=document.querySelector('#ps-chat-actions'),psError=document.querySelector('#ps-chat-error'),psToggle=document.querySelector('#ps-chat-toggle');function psSay(text,isUser=false){psMessages.append(psSafe('div',`ps-chat-message${isUser?' is-user':''}`,text));psChat.querySelector('.ps-chat-body').scrollTop=psChat.querySelector('.ps-chat-body').scrollHeight}function psAction(label,handler,primary=false){const button=psSafe('button',primary?'primary':'',label);button.type='button';button.addEventListener('click',handler);return button}function psCloseChat(reset=true){psChat.classList.remove('open');psChat.setAttribute('aria-hidden','true');psToggle.setAttribute('aria-expanded','false');if(reset){psAnswers={};psStep=0;psMessages.replaceChildren();psControls.replaceChildren();psActions.replaceChildren();psError.textContent=''}}
        function psRenderQuestion(){psControls.replaceChildren();psActions.replaceChildren();psError.textContent='';if(psStep>=psQuestions.length){psSay('Periksa kembali usulan sebelum dikirim.');psSay(`${psAnswers.title}\n${psAnswers.location}\n${psAnswers.description}`);psActions.append(psAction('Batal',()=>psCloseChat()),psAction('Kirim usulan',psSubmitProposal,true));return}const question=psQuestions[psStep];psSay(question.prompt);psControls.append(psSafe('div','ps-chat-prompt',`${psStep+1} dari ${psQuestions.length}`));if(question.type==='choice'){const options=document.createElement('div');options.className='ps-chat-options';question.options.forEach(option=>options.append(psAction(option,()=>{psAnswers[question.key]=option;psSay(option,true);psStep++;psRenderQuestion()})));psControls.append(options)}else{const input=document.createElement(question.type==='textarea'?'textarea':'input');input.className='ps-chat-input';input.placeholder=question.key==='title'?'Judul usulan':question.key==='location'?'Lokasi':question.key==='description'?'Uraian singkat':question.key==='name'?'Nama':'Kontak';input.setAttribute('aria-label',input.placeholder);input.maxLength=question.key==='description'?3000:160;if(question.type==='textarea')input.rows=3;psControls.append(input)}psActions.append(psAction('Batal',()=>psCloseChat()));if(!question.required)psActions.append(psAction('Lewati',()=>{psAnswers[question.key]='';psStep++;psRenderQuestion()}));psActions.append(psAction(psStep===psQuestions.length-1?'Tinjau':'Lanjut',()=>{const input=psControls.querySelector('input,textarea'),value=input?.value.trim()||'';if(question.required&&!value){psError.textContent='Bagian ini perlu diisi.';return}psAnswers[question.key]=value;if(value)psSay(value,true);psStep++;psRenderQuestion()},true))}async function psSubmitProposal(){psError.textContent='';const send=psActions.querySelector('.primary');send.disabled=true;try{const response=await fetch('/api/desa/pesisir/proposals',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},body:JSON.stringify({...psAnswers,website:''})});const result=response.status===204?{}:await response.json();if(!response.ok)throw new Error(result.message||'Usulan belum berhasil dikirim.');psMessages.replaceChildren();psControls.replaceChildren();psActions.replaceChildren();psSay(result.message||'Usulan berhasil dikirim.');psActions.append(psAction('Selesai',()=>psCloseChat(),true))}catch(exception){psError.textContent=exception.message;send.disabled=false}}psToggle.addEventListener('click',()=>{const open=!psChat.classList.contains('open');psChat.classList.toggle('open',open);psChat.setAttribute('aria-hidden',String(!open));psToggle.setAttribute('aria-expanded',String(open));if(open&&!psMessages.childElementCount)psRenderQuestion()});document.querySelector('#ps-chat-close').addEventListener('click',()=>psCloseChat(false));
    </script>
    @include('desa.partials.responsive')
</body>
</html>
